              <div class="data-item"><div class="data-key">已掌握功法</div><div class="data-value">${masteredSkills}</div></div>
              <div class="data-item"><div class="data-key">已掌握武技</div><div class="data-value">${masteredMartialArts}</div></div>
            </div>
          </div>

          <div class="data-section">
            <div class="section-title">🎒 物品与资产</div>
            <div class="section-body">
              <div class="data-item"><div class="data-key">现有物品</div><div class="data-value">${playerData['现有物品'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">灵宠</div><div class="data-value">${playerData['灵宠'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">现有资产</div><div class="data-value">${playerData['现有资产'] || '无'}</div></div>
            </div>
          </div>

          <div class="data-section">
            <div class="section-title">❤️ 道侣与同伴</div>
            <div class="section-body">
              <div class="data-item"><div class="data-key">道侣</div><div class="data-value">${playerData['道侣（有情感与契约绑定的修行伴侣）'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">同伴</div><div class="data-value">${playerData['同伴（一起行动的修行伙伴）'] || '无'}</div></div>
            </div>
          </div>`;
        contentArea.innerHTML = html;
      }

      // 渲染任务栏
      function renderQuestBoard(questData) {
        const area = document.getElementById('quest-content-area');
        if (!area || !questData.length) return;
        const quests = questData[0];
        let html = '', idx = 1;
        while (quests[`任务${idx}_名称`]) {
          html += `<div class="task-card">
            <div class="task-title">${quests[`任务${idx}_名称`]}</div>
            <div>进度: ${quests[`任务${idx}_进度`] || '0/0'}</div>
            <div>要求: ${quests[`任务${idx}_要求`] || '无'}</div>
            <div>奖励: ${quests[`任务${idx}_奖励`] || '无'}</div>
            <div>提示: ${quests[`任务${idx}_提示`] || ''}</div>
          </div>`;
          idx++;
        }
        area.innerHTML = html;
      }

      // 渲染同伴状态
      function renderCompanionStatus(companions) {
        const contentArea = document.getElementById('companion-content-area');
        if (!contentArea || !companions) return;

        if (companions.length === 0) {
          contentArea.innerHTML = '<p>无同伴信息</p>';
          return;
        }

        let html = '';
        companions.forEach((npc) => {
          html += `<div class="data-section">
            <div class="section-title">姓名: ${npc['姓名'] || '无名'}</div>
            <div class="section-body">
              <div class="data-item"><div class="data-key">关系</div><div class="data-value">${npc['关系'] || npc['关系:'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">性别</div><div class="data-value">${npc['性别'] || '未知'}</div></div>
              <div class="data-item"><div class="data-key">灵根</div><div class="data-value">${npc['灵根'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">修为</div><div class="data-value">${npc['修为'] || '无'}</div></div>
              <div class="data-item"><div class="data-key">对玩家好感度</div><div class="data-value">${npc[`对${npc['基本信息'] || '{{user}}'}好感度`] || npc['对{{user}}好感度'] || npc['对玩家好感度'] || '未知'}</div></div>
              <div class="data-item"><div class="data-key">对玩家看法</div><div class="data-value">${npc[`对${npc['基本信息'] || '{{user}}'}看法`] || npc['对{{user}}看法'] || npc['对玩家看法'] || '无'}</div></div>
            </div>
          </div>`;
        });
        contentArea.innerHTML = html;
      }

      // 初始化折叠面板状态（全部折叠）
      function initCollapse() {
        const headers = document.querySelectorAll('.collapsible-header');
        headers.forEach(header => {
          const panel = header.nextElementSibling;
          panel.style.maxHeight = null;
          header.classList.remove('active');
          header.querySelector('.arrow').textContent = '▶';

          header.addEventListener('click', () => {
            const isActive = header.classList.contains('active');
            if (isActive) {
              panel.style.maxHeight = null;
              header.classList.remove('active');
              header.querySelector('.arrow').textContent = '▶';
            } else {
              panel.style.maxHeight = panel.scrollHeight + 'px';
              header.classList.add('active');
              header.querySelector('.arrow').textContent = '▼';
            }
          });
        });
      }

      // 主流程
      const rawText = dataContainer.textContent.trim();
      const parsedData = parseData(rawText);

      // 渲染所有面板数据
      if (parsedData['PlayerState'] && parsedData['PlayerState'].length > 0) {
        renderPlayerStatus(parsedData['PlayerState'][0]);
      }
      if (parsedData['QuestBoard']) {
        renderQuestBoard(parsedData['QuestBoard']);
      }
      if (parsedData['Mate']) {
        renderCompanionStatus(parsedData['Mate']);
      }

      initCollapse();
    });
  </script>
</body>
</html>
